import java.util.*;

class Student {
    String name;
    List<Integer> scores;

    Student(String name, List<Integer> scores) {
        this.name = name;
        this.scores = scores;
    }

    double average() {
        int sum = 0;
        for (int s : scores) sum += s;
        return (double) sum / scores.size();
    }
}

public class Main {
    public static void main(String[] args) {
        List<Student> students = List.of(
            new Student("Ava", List.of(90, 85, 98)),
            new Student("Ben", List.of(70, 65, 81)),
            new Student("Cy", List.of(88, 92, 79))
        );

        Student best = students.get(0);
        for (Student s : students) {
            System.out.printf("%s: %.1f%n", s.name, s.average());
            if (s.average() > best.average()) best = s;
        }
        System.out.println("Top student: " + best.name);
    }
}

